18	/// Content of the scaffolded `.changeset/README.md`.
19	pub const CHANGESET_README: &str = "# Changesets
20	
21	This directory contains markdown changeset files generated by Callisto CLI (`callisto add`).
22	Each changeset describes a package version bump and associated release summary.
23	";
24	
25	const CONFIG_HEADER: &str = "# callisto configuration\n";
26	const DEFAULT_TAG_CONVENTION: &str = "{name}@{version}";
27	const SHARED_TAG_CONVENTION: &str = "v{version}";
28	const TAG_CONVENTIONS: [&str; 4] = [
29	    DEFAULT_TAG_CONVENTION,
30	    "{name}-v{version}",
31	    "{name}-{version}",
32	    SHARED_TAG_CONVENTION,
33	];
