35	/// How packages version relative to each other.
36	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
37	pub enum Versioning {
38	    /// Every package shares one version (`[[fixed-group]] name = "all"`).
39	    Fixed,
40	    Independent,
41	}
42	
43	/// One discovered workspace package.
44	#[derive(Clone, Debug, PartialEq, Eq)]
45	pub struct InitPackage {
46	    /// Ecosystem-qualified id, e.g. `cargo/app`.
47	    pub id: String,
48	    pub version: Version,
49	    /// Executables the package builds; empty for a library.
50	    pub bin_names: Vec<String>,
51	    /// Executables provided by Cargo and eligible for Cargo artifact builds.
52	    pub cargo_bin_names: Vec<String>,
53	    /// Ecosystems that provide executables but do not yet have an artifact builder.
54	    pub unsupported_bin_ecosystems: Vec<String>,
55	    /// Latest release tag under the package's detected convention.
56	    pub last_tag: Option<TagName>,
57	    /// Detected `publish-to` targets (`none` omitted).
58	    pub publish_to: Vec<String>,
59	    /// A napi/maturin platform package: never grouped or shipped.
60	    pub platform: bool,
61	}
62	
63	impl InitPackage {
64	    pub fn is_binary(&self) -> bool {
65	        !self.platform && !self.bin_names.is_empty()
66	    }
67	
68	    fn supports_artifact_builder(&self) -> bool {
69	        self.id.starts_with("cargo/") && !self.cargo_bin_names.is_empty()
70	    }
71	
72	    fn name(&self) -> &str {
73	        self.id.split_once('/').map_or(self.id.as_str(), |(_, name)| name)
74	    }
75	}
