77	/// Everything `init` detects before asking a question.
78	#[derive(Clone, Debug)]
79	pub struct InitFacts {
80	    pub root: PathBuf,
81	    pub ecosystems: BTreeSet<Ecosystem>,
82	    pub packages: Vec<InitPackage>,
83	    /// Canonical `origin` push URL, or `None` when no `origin` remote is configured.
84	    pub origin: Option<String>,
85	    /// `origin` as a GitHub `owner/repo`, when it is one.
86	    pub origin_repository: Option<GitHubRepository>,
87	    /// Non-default tag templates to write, keyed by qualified package id.
88	    pub tag_templates: BTreeMap<String, String>,
89	    /// `false` in a repository with no commit yet, where no release can be planned.
90	    pub has_commit: bool,
91	    /// A package ships napi/maturin platform builds -- either its own canonical
92	    /// manifest is platform-tagged, or a platform package is attached to it from
93	    /// a sibling directory (`IdentityIndex::platforms_of`, e.g. napi's per-arch
94	    /// packages). Mirrors `commands::release::local::ci_release_route`'s own
95	    /// platform-package check.
96	    pub has_platform_packages: bool,
97	    /// Some package declares `napi.targets` (`callisto matrix`'s napi entries).
98	    pub has_napi_targets: bool,
99	    /// Some package declares `[tool.maturin].targets`.
100	    pub has_maturin_targets: bool,
101	}
102	
103	impl InitFacts {
104	    pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
105	        self.packages
106	            .iter()
107	            .filter(|package| package.is_binary() && package.supports_artifact_builder())
108	    }
109	
110	    pub fn unsupported_artifact_packages(&self) -> impl Iterator<Item = &InitPackage> {
111	        self.packages
112	            .iter()
113	            .filter(|package| !package.supports_artifact_builder() && !package.unsupported_bin_ecosystems.is_empty())
114	    }
115	
116	    /// Resolves `name` (qualified or bare) to a binary-producing package.
117	    pub fn product_package(&self, name: &str) -> Result<&InitPackage, GraphError> {
118	        let invalid = |reason| GraphError::InitInvalidProductPackage {
119	            package: name.to_owned(),
120	            reason,
121	            candidates: self.binary_packages().map(|package| package.id.clone()).collect(),
122	        };
123	        let found: Vec<&InitPackage> = match self.packages.iter().find(|package| package.id == name) {
124	            Some(package) => vec![package],
125	            None => self.packages.iter().filter(|package| package.name() == name).collect(),
126	        };
127	        match found.as_slice() {
128	            [package] if package.is_binary() && package.supports_artifact_builder() => Ok(package),
129	            [package] if package.is_binary() => Err(GraphError::InitUnsupportedArtifactBuilder {
130	                package: package.id.clone(),
131	                ecosystem: package.unsupported_bin_ecosystems.first().cloned().unwrap_or_else(|| {
132	                    package
133	                        .id
134	                        .split_once('/')
135	                        .map_or("unknown", |(ecosystem, _)| ecosystem)
136	                        .to_owned()
137	                }),
138	            }),
139	            [_] => Err(invalid("it does not produce a binary artifact")),
140	            _ => Err(invalid("it is not a workspace package")),
141	        }
142	    }
143	}
