167	fn ensure_uninitialized(root: &Path) -> Result<(), GraphError> {
168	    let path = root.join("callisto.toml");
169	    if callisto_model::strict_fs::exists(&path).map_err(io_err(&path))? {
170	        return Err(GraphError::InitAlreadyInitialized { path });
171	    }
172	    Ok(())
173	}
174	
175	fn qualified_id(package: &callisto_model::Package) -> String {
176	    match package.canonical_manifests().next() {
177	        Some(manifest) => format!("{}/{}", manifest.ecosystem().prefix(), package.id.name()),
178	        None => package.id.display_name(),
179	    }
180	}
