182	/// Detects the workspace facts `init` reports and builds on.
183	///
184	/// # Errors
185	///
186	/// An existing `callisto.toml`, no Git repository, no usable `origin`, or an
187	/// ambiguous tag convention.
188	pub fn detect<L: ProjectLocator, R: CommandRunner>(
189	    root: &Path,
190	    locator: &L,
191	    runner: &R,
192	) -> Result<InitFacts, GraphError> {
193	    let root = canonical_root(root)?;
194	    ensure_uninitialized(&root)?;
195	    detect_facts(root, locator, runner, false)
196	}
