198	/// [`detect`] for a workspace that already has a `callisto.toml`, which is left as it is.
199	///
200	/// # Errors
201	///
202	/// No Git repository, or no usable `origin`. The workspace loads through the existing config.
203	pub fn detect_initialized<L: ProjectLocator, R: CommandRunner>(
204	    root: &Path,
205	    locator: &L,
206	    runner: &R,
207	) -> Result<InitFacts, GraphError> {
208	    detect_facts(canonical_root(root)?, locator, runner, true)
209	}
