211	/// Whether `root` already has a `callisto.toml`.
212	///
213	/// # Errors
214	///
215	/// The path cannot be inspected.
216	pub fn is_initialized(root: &Path) -> Result<bool, GraphError> {
217	    let path = root.join("callisto.toml");
218	    callisto_model::strict_fs::exists(&path).map_err(io_err(&path))
219	}
