221	/// Whether the existing `callisto.toml` declares a product whose binaries ship as release assets.
222	///
223	/// # Errors
224	///
225	/// The file cannot be read or does not resolve, or an artifact's owner is not a Cargo package.
226	pub fn existing_config_ships_binaries(root: &Path) -> Result<bool, GraphError> {
227	    let path = root.join("callisto.toml");
228	    let text = callisto_model::strict_fs::read_optional(&path)
229	        .map_err(io_err(&path))?
230	        .unwrap_or_default();
231	    let Some(release) = resolve_config_text(root, &text)?.product_release else {
232	        return Ok(false);
233	    };
234	    // The generated builder builds Cargo artifacts only; the matrix drops any other owner.
235	    if let Some(artifact) = release
236	        .artifacts
237	        .iter()
238	        .find(|artifact| artifact.package.ecosystem() != Some(Ecosystem::Cargo))
239	    {
240	        return Err(GraphError::InitUnsupportedArtifactBuilder {
241	            package: artifact.package.display_name(),
242	            ecosystem: artifact
243	                .package
244	                .ecosystem()
245	                .map_or_else(|| "unknown".to_owned(), |ecosystem| ecosystem.prefix().to_owned()),
246	        });
247	    }
248	    Ok(true)
249	}
