251	fn detect_facts<L: ProjectLocator, R: CommandRunner>(
252	    root: PathBuf,
253	    locator: &L,
254	    runner: &R,
255	    initialized: bool,
256	) -> Result<InitFacts, GraphError> {
257	    let git_dir = runner.run_with_timeout(programs::GIT, &["rev-parse", "--git-dir"], &root, timeouts::LOCAL_GIT)?;
258	    if git_dir.exit_code != Some(0) {
259	        return Err(GraphError::InitNotGitRepository { root });
260	    }
261	    let origin = optional_git_remote(&root, runner)?;
262	    let head = runner.run_with_timeout(
263	        programs::GIT,
264	        &["rev-parse", "--verify", "--quiet", "HEAD"],
265	        &root,
266	        timeouts::LOCAL_GIT,
267	    )?;
268	
269	    let discovered = Workspace::load(root.clone(), locator, runner)?;
270	    // An existing config already decides tag conventions; synthesizing one would second-guess it.
271	    let tag_templates = if initialized {
272	        BTreeMap::new()
273	    } else {
274	        detect_tag_templates(&discovered)?
275	    };
276	    let templates_only = InitFacts {
277	        root: root.clone(),
278	        ecosystems: BTreeSet::new(),
279	        packages: Vec::new(),
280	        origin: origin.as_ref().map(|remote| remote.endpoint.clone()),
281	        origin_repository: origin.as_ref().and_then(|remote| remote.github_repository.clone()),
282	        tag_templates,
283	        has_commit: head.exit_code == Some(0),
284	        has_platform_packages: false,
285	        has_napi_targets: false,
286	        has_maturin_targets: false,
287	    };
288	    let workspace = if initialized {
289	        discovered
290	    } else {
291	        let config = resolve_config_text(
292	            &root,
293	            &render_config(
294	                &templates_only,
295	                &InitAnswers {
296	                    versioning: Versioning::Independent,
297	                    binaries: None,
298	                },
299	            ),
300	        )?;
301	        Workspace::load_with_config(root.clone(), config, locator, runner)?
302	    };
303	    let tags = workspace.tags()?;
304	    let versions = workspace.base_versions()?;
305	    let ctx = callisto_manifests::OpenContext::for_workspace_root(&workspace.root)?;
306	
307	    let mut packages = Vec::new();
308	    for package in workspace.graph.packages() {
309	        let mut bin_names = Vec::new();
310	        let mut cargo_bin_names = Vec::new();
311	        let mut unsupported_bin_ecosystems = BTreeSet::new();
312	        for decl in package.canonical_manifests() {
313	            let manifest = crate::manifest_cache::open_cached(&workspace.manifest_cache, decl, &ctx)?;
314	            let names = manifest.bin_names()?;
315	            if manifest.ecosystem() == Ecosystem::Cargo {
316	                cargo_bin_names.extend(names.iter().cloned());
317	            } else if !names.is_empty() {
318	                unsupported_bin_ecosystems.insert(manifest.ecosystem().prefix().to_owned());
319	            }
320	            bin_names.extend(names);
321	        }
322	        packages.push(InitPackage {
323	            id: qualified_id(package),
324	            version: versions[&package.id].clone(),
325	            bin_names,
326	            cargo_bin_names,
327	            unsupported_bin_ecosystems: unsupported_bin_ecosystems.into_iter().collect(),
328	            last_tag: tags.last_tag(&package.id).map(|tag| tag.name.clone()),
329	            publish_to: package
330	                .publish_to
331	                .iter()
332	                .map(|target| target.config_str().to_owned())
333	                .filter(|target| target != PublishTarget::None.config_str())
334	                .collect(),
335	            platform: is_platform_package(package),
336	        });
337	    }
338	    packages.sort_by(|a, b| a.id.cmp(&b.id));
339	    let ecosystems = workspace
340	        .graph
341	        .packages()
342	        .flat_map(|package| package.canonical_manifests())
343	        .map(|manifest| manifest.ecosystem())
344	        .collect();
345	    // Counts attached platform packages too: they never get their own `packages` entry,
346	    // so scanning canonical manifests alone finds only co-located ones.
347	    let has_platform_packages = workspace
348	        .graph
349	        .packages()
350	        .any(|package| is_platform_package(package) || workspace.identity.platforms_of(&package.id).next().is_some());
351	
352	    let matrix = crate::commands::matrix::matrix(&workspace, &crate::commands::matrix::MatrixOptions::default())?;
353	    let has_kind = |kind| matrix.platform_targets.values().any(|group| group.kind == kind);
354	
355	    Ok(InitFacts {
356	        ecosystems,
357	        packages,
358	        has_platform_packages,
359	        has_napi_targets: has_kind(callisto_model::PlatformTargetKind::Napi),
360	        has_maturin_targets: has_kind(callisto_model::PlatformTargetKind::Maturin),
361	        ..templates_only
362	    })
363	}
