365	/// One tag convention a package's existing tags follow.
366	struct TagMatch {
367	    convention: &'static str,
368	    template: String,
369	    tags: Vec<String>,
370	}
371	
372	/// Matches each package's tags against the candidate conventions; returns the non-default ones to write.
373	fn detect_tag_templates<R: CommandRunner, D: DependencyResolver>(
374	    workspace: &Workspace<'_, R, D>,
375	) -> Result<BTreeMap<String, String>, GraphError> {
376	    let all_tags = crate::tags::fetch_all_tags(workspace.git_access())?;
377	    let mut matches: BTreeMap<String, Vec<TagMatch>> = BTreeMap::new();
378	    for package in workspace
379	        .graph
380	        .packages()
381	        .filter(|package| !is_platform_package(package))
382	    {
383	        let grammar = package.version_grammar()?;
384	        for convention in TAG_CONVENTIONS {
385	            let rendered = if convention == DEFAULT_TAG_CONVENTION {
386	                TagTemplate::default_for(&package.id).as_str()
387	            } else {
388	                convention.replace("{name}", package.id.name())
389	            };
390	            let Ok(template) = TagTemplate::parse(&rendered) else {
391	                continue;
392	            };
393	            // A leading digit keeps `{name}-{version}` from claiming `{name}-v1.0.0` under PEP 440.
394	            let tags: Vec<String> = all_tags
395	                .iter()
396	                .filter(|tag| {
397	                    template.extract_version_str(tag).is_some_and(|version| {
398	                        version.starts_with(|c: char| c.is_ascii_digit()) && Version::parse(version, grammar).is_ok()
399	                    })
400	                })
401	                .cloned()
402	                .collect();
403	            if !tags.is_empty() {
404	                matches.entry(qualified_id(package)).or_default().push(TagMatch {
405	                    convention,
406	                    template: rendered,
407	                    tags,
408	                });
409	            }
410	        }
411	    }
412	
413	    let shared: Vec<String> = matches
414	        .iter()
415	        .filter(|(_, found)| found.iter().any(|found| found.convention == SHARED_TAG_CONVENTION))
416	        .map(|(package, _)| package.clone())
417	        .collect();
418	    if shared.len() > 1 {
419	        return Err(GraphError::InitSharedVersionTag { packages: shared });
420	    }
421	
422	    let mut templates = BTreeMap::new();
423	    for (package, found) in matches {
424	        match found.as_slice() {
425	            [only] => {
426	                if only.convention != DEFAULT_TAG_CONVENTION {
427	                    templates.insert(package, only.template.clone());
428	                }
429	            }
430	            _ => {
431	                return Err(GraphError::InitTagTemplateAmbiguous {
432	                    package,
433	                    matches: found
434	                        .iter()
435	                        .map(|found| format!("`{}` ({})", found.template, found.tags.join(", ")))
436	                        .collect(),
437	                })
438	            }
439	        }
440	    }
441	    Ok(templates)
442	}
