444	/// Renders `callisto.toml` from the answers: only answered intent and tag continuity, never defaults.
445	pub fn render_config(facts: &InitFacts, answers: &InitAnswers) -> String {
446	    use toml_edit::{value, Array, ArrayOfTables, DocumentMut, Item, Table};
447	
448	    let mut doc = DocumentMut::new();
449	    if answers.versioning == Versioning::Fixed {
450	        let members: Array = facts
451	            .packages
452	            .iter()
453	            .filter(|package| !package.platform)
454	            .map(|package| package.id.as_str())
455	            .collect();
456	        if !members.is_empty() {
457	            let mut group = Table::new();
458	            group["name"] = value("all");
459	            group["members"] = value(members);
460	            let mut groups = ArrayOfTables::new();
461	            groups.push(group);
462	            doc["fixed-group"] = Item::ArrayOfTables(groups);
463	        }
464	    }
465	    let mut rules: BTreeMap<&str, Table> = BTreeMap::new();
466	    for (package, template) in &facts.tag_templates {
467	        rules.entry(package).or_default()["tag-template"] = value(template.as_str());
468	    }
469	    let product = answers
470	        .binaries
471	        .as_ref()
472	        .and_then(|release| facts.packages.iter().find(|package| package.id == release.product));
473	    if let Some(product) = product {
474	        // Artifact slots derive only for a product that publishes to github-release.
475	        let publish_to: Array = product
476	            .publish_to
477	            .iter()
478	            .map(String::as_str)
479	            .chain([PublishTarget::GitHubRelease.config_str()])
480	            .collect();
481	        rules.entry(&product.id).or_default()["publish-to"] = value(publish_to);
482	    }
483	    if !rules.is_empty() {
484	        let mut tables = ArrayOfTables::new();
485	        for (package, rule) in rules {
486	            let mut table = Table::new();
487	            table["match"] = value(package);
488	            table.extend(rule);
489	            tables.push(table);
490	        }
491	        doc["package"] = Item::ArrayOfTables(tables);
492	    }
493	    if let Some(release) = &answers.binaries {
494	        // One archive holds every binary of the package, so a package with several is named after the package.
495	        let asset_stem = match product.map(|package| package.cargo_bin_names.as_slice()) {
496	            Some([only]) => only.as_str(),
497	            _ => release
498	                .product
499	                .split_once('/')
500	                .map_or(release.product.as_str(), |(_, name)| name),
501	        };
502	        let (windows, others): (Vec<&String>, Vec<&String>) =
503	            release.targets.iter().partition(|target| target.contains("windows"));
504	        let mut table = Table::new();
505	        table["product-package"] = value(release.product.as_str());
506	        if !others.is_empty() {
507	            table["targets"] = value(others.iter().map(|target| target.as_str()).collect::<Array>());
508	            table["asset-name"] = value(format!("{asset_stem}-{{target}}.tar.gz"));
509	        }
510	        // A Windows archive is a `.zip`, which the one template cannot name.
511	        let mut artifacts = ArrayOfTables::new();
512	        for target in windows {
513	            let mut artifact = Table::new();
514	            artifact["package"] = value(release.product.as_str());
515	            artifact["target"] = value(target.as_str());
516	            artifact["asset-name"] = value(format!("{asset_stem}-{target}.zip"));
517	            artifacts.push(artifact);
518	        }
519	        if !artifacts.is_empty() {
520	            table["artifact"] = Item::ArrayOfTables(artifacts);
521	        }
522	        doc["release"] = Item::Table(table);
523	    }
524	    let body = doc.to_string();
525	    if body.is_empty() {
526	        CONFIG_HEADER.to_owned()
527	    } else {
528	        format!("{CONFIG_HEADER}\n{body}")
529	    }
530	}
