532	fn resolve_config_text(root: &Path, text: &str) -> Result<ResolvedConfig, GraphError> {
533	    let raw = crate::config::resolve::parse_raw(&root.join("callisto.toml"), text)?;
534	    Ok(crate::config::resolve(root, raw)?)
535	}
