537	/// The first release `config` would produce, from the plan behind `release --dry-run`.
538	///
539	/// # Errors
540	///
541	/// `config` fails to resolve, or the release plan cannot be derived.
542	pub fn preview<L: ProjectLocator, R: CommandRunner>(
543	    facts: &InitFacts,
544	    config: &str,
545	    locator: &L,
546	    runner: &R,
547	) -> Result<Option<LocalReleasePlan>, GraphError> {
548	    let resolved = resolve_config_text(&facts.root, config)?;
549	    let workspace = Workspace::load_with_config(facts.root.clone(), resolved, locator, runner)?;
550	    plan_workspace_release(&workspace, &[], LocalReleaseSource::Preview)
551	}
