553	/// Validates artifact target triples.
554	///
555	/// # Errors
556	///
557	/// An empty or repeated triple.
558	pub fn validate_targets(targets: &[String]) -> Result<Vec<String>, GraphError> {
559	    let mut seen = BTreeSet::new();
560	    for target in targets {
561	        let invalid = |reason| GraphError::InitInvalidTargetTriple {
562	            triple: target.clone(),
563	            reason,
564	        };
565	        if target.trim().is_empty() {
566	            return Err(invalid("it is empty"));
567	        }
568	        if !seen.insert(target.as_str()) {
569	            return Err(invalid("it is given more than once"));
570	        }
571	    }
572	    Ok(targets.to_vec())
573	}
