575	/// Files `init` writes, or would write under `--dry-run`: `callisto.toml`, `.changeset/README.md`
576	/// unless it already exists, and the release workflow when `workflow` is `true`. Reads current
577	/// disk state, so callers compute this before writing anything.
578	///
579	/// # Errors
580	///
581	/// The README's existence cannot be determined.
582	pub fn init_files(root: &Path, workflow: bool) -> Result<Vec<PathBuf>, GraphError> {
583	    let readme = root.join(".changeset/README.md");
584	    let mut files = vec![root.join("callisto.toml")];
585	    if !callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
586	        files.push(readme);
587	    }
588	    if workflow {
589	        files.push(workflow_path(root));
590	    }
591	    Ok(files)
592	}
593	
594	/// Writes `callisto.toml` and, when absent, `.changeset/README.md`.
595	///
596	/// # Errors
597	///
598	/// `callisto.toml` already exists, or a write fails.
599	pub fn write(root: &Path, config: &str, permit: &ApplyPermit) -> Result<InitReport, GraphError> {
600	    ensure_uninitialized(root)?;
601	    let config_path = root.join("callisto.toml");
602	    let files = init_files(root, false)?;
603	    callisto_model::atomic::atomic_write(&config_path, config, permit).map_err(io_err(&config_path))?;
604	    write_changeset_readme(root, permit)?;
605	    Ok(InitReport {
606	        schema_version: SCHEMA_VERSION,
607	        initialized: true,
608	        config_path,
609	        config: config.to_owned(),
610	        files,
611	        diagnostics: Vec::new(),
612	    })
613	}
614	
615	/// Creates `.changeset/README.md` unless it already exists.
616	///
617	/// # Errors
618	///
619	/// A directory or file write fails.
620	pub fn write_changeset_readme(root: &Path, permit: &ApplyPermit) -> Result<(), GraphError> {
621	    let readme = root.join(".changeset/README.md");
622	    if callisto_model::strict_fs::exists(&readme).map_err(io_err(&readme))? {
623	        return Ok(());
624	    }
625	    let changeset_dir = root.join(".changeset");
626	    std::fs::create_dir_all(&changeset_dir).map_err(io_err(&changeset_dir))?;
627	    callisto_model::atomic::atomic_write(&readme, CHANGESET_README, permit).map_err(io_err(&readme))
628	}
629	
630	/// `@changesets/cli` `config.json` keys callisto never reads, and the callisto.toml construct
631	/// that replaces each one, when one exists.
632	const CHANGESETS_CONFIG_KEYS: [(&str, Option<&str>); 6] = [
633	    ("fixed", Some("[[fixed-group]]")),
634	    ("linked", None),
635	    ("ignore", None),
636	    ("access", None),
637	    ("baseBranch", None),
638	    ("updateInternalDependencies", None),
639	];
640	
641	/// Warns, per key, about every `.changeset/config.json` key callisto ignores.
642	///
643	/// callisto never translates this file; a present, unhonoured key is silently inert otherwise.
644	/// Returns no diagnostics when the file is absent or is not a JSON object.
645	pub fn changesets_config_diagnostics(root: &Path) -> Vec<Diagnostic> {
646	    let path = root.join(".changeset/config.json");
647	    let Ok(text) = std::fs::read_to_string(&path) else {
648	        return Vec::new();
649	    };
650	    let Ok(serde_json::Value::Object(config)) = serde_json::from_str(&text) else {
651	        return Vec::new();
652	    };
653	    CHANGESETS_CONFIG_KEYS
654	        .iter()
655	        .filter(|(key, _)| config.contains_key(*key))
656	        .map(|(key, equivalent)| {
657	            let message = match equivalent {
658	                Some(equivalent) => {
659	                    format!("`.changeset/config.json` key `{key}` is not honoured; use {equivalent} instead")
660	                }
661	                None => format!("`.changeset/config.json` key `{key}` is not honoured; callisto has no equivalent"),
662	            };
663	            Diagnostic {
664	                code: DiagnosticCode::ChangesetsConfigKeyDropped,
665	                severity: DiagnosticSeverity::Warning,
666	                message,
667	                package: None,
668	                path: Some(path.clone()),
669	                escalated_by: None,
670	                governed_by: None,
671	            }
672	        })
673	        .collect()
674	}
675	
676	/// The config `write` would produce for `root` with no answers: a header only.
677	pub fn empty_config() -> &'static str {
678	    CONFIG_HEADER
679	}
680	
681	/// Path `init` writes a generated GitHub Actions release workflow to: the one
682	/// workflow `release plan` binds artifact attestations to.
683	pub fn workflow_path(root: &Path) -> PathBuf {
684	    root.join(callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH)
685	}
686	
687	/// Which release workflow `init` generates.
688	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
689	pub enum WorkflowShape {
690	    /// Two jobs: `version-pr` and `callisto release`.
691	    Simple,
692	    /// `version-pr` plus plan -> build (matrix) -> execute,
693	    /// for `[[release.artifact]]` slots or napi platform packages.
694	    BuildMatrix,
695	}
696	
697	/// Why `init` generates no workflow for a workspace.
698	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
699	pub enum WorkflowUnsupported {
700	    /// maturin platform builds have no generated build job.

