    let needle = format!("`{key}`");
    let found: Vec<&str> = messages(migration)
        .into_iter()
        .filter(|message| message.contains(&needle))
        .collect();
    assert_eq!(found.len(), 1, "one warning names {needle}: {:?}", messages(migration));
