    assert_eq!(
        migration.fixed_groups,
        vec![FixedGroup {
            name: "fixed-1".to_owned(),
            members: ["npm/@acme/cli", "npm/@acme/core", "npm/@acme/utils"]
                .map(str::to_owned)
