}

fn run_init_with_runner<R: CommandRunner>(
    root: &Path,
    args: InitArgs,
    interactive: bool,
    answers: Vec<Answer>,
    dry_run: bool,
    runner: &R,
) -> Run {
    let out = Shared::default();
    let err = Shared::default();
    let mut prompter = Scripted::new(answers, &out);
    let result = run(
        args,
        &global(root, OutputFormat::Text, dry_run),
        interactive,
        &mut prompter,
        &mut out.clone(),
        &mut err.clone(),
        runner,
    );
    Run {
        result,
        out: out.text(),
        prompter,
    }
}

