    );
    let config = std::fs::read_to_string(dir.path().join("callisto.toml")).unwrap();

    let retry = InitArgs {
        workflow: true,
        ..Default::default()
    };
    let run = run_init_with_runner(
        dir.path(),
        retry,
        false,
